-- ProTrack: is every update from v18 to v34 installed? Supabase -> SQL Editor -> New query -> paste -> Run.
-- Reads only, changes nothing. One row per update: OK when what it installs is all there.
select v, got, expected, case when got = expected then 'OK' else 'CHECK' end as status from (values
('v18', (select count(*) from pg_proc where proname in ('pt_mat_snapshot','pt_xr_layout_ok')) + (select count(*) from information_schema.tables where table_schema='public' and table_name in ('xr_layout_default','xr_layouts')) + (select count(*) from information_schema.columns where table_schema='public' and table_name='report_releases' and column_name='mat_snapshot'), 5),
('v20', (select count(*) from pg_proc where proname in ('pt_contract_of','pt_vo_check','pt_release_contract','vo_update')) + (select count(*) from information_schema.tables where table_schema='public' and table_name='co_log_updates') + (select count(*) from information_schema.columns where table_schema='public' and ((table_name='co_log' and column_name in ('client_price','internal_price','wf_no','wf_date')) or (table_name='report_releases' and column_name='contract_snapshot'))), 10),
('v21', (select count(*) from pg_proc where proname = 'tender_features') + (select count(*) from information_schema.columns where table_schema='public' and table_name='projects' and column_name in ('bid_rank','rank_note','fwbs_on','noa_by')) + (case when 'tender.noa' = any(pt_rights()) then 1 else 0 end), 6),
('v22', (select count(*) from pg_proc where proname in ('release_act_bl','pt_bl_cmp','pt_inv_phase','pt_proj_billing','bl_cash_features')) + (select count(*) from information_schema.columns where table_schema='public' and ((table_name='schedule_updates' and column_name='bl_src') or (table_name='schedule_update_rows' and column_name in ('xbs','xbf')) or (table_name='invoices' and column_name in ('phase','sub_date','appr_date','coll_date')))) + (select count(*) from pg_trigger where tgname='trg_proj_billing'), 13),
('v23', (select count(*) from pg_proc where proname in ('report_mail_set','release_act_cv','margin_mail_features','pt_release_cvby','pt_cost_cv_by','pt_cv_cols','pt_rel_mail_reader','pt_rel_mail_region_keeper','pt_mail_roles')) + (select count(*) from pg_trigger where tgname='trg_rr_cvby') + (select count(*) from report_mail_lists where region_id is null) + (select count(*) from pg_policies where tablename='report_mail_lists'), 13),
('v24', (select count(*) from pg_proc where proname in ('delay_act','delay_import','delay_features','pt_dly_keeper','pt_dly_status','pt_dly_nokey','pt_dly_num','pt_dly_numtext','pt_dly_label','pt_dly_keys','pt_dly_merge','pt_dly_log','pt_dly_write')) + (select count(*) from pg_tables where tablename in ('delay_events','delay_audit')) + (select count(*) from pg_policies where tablename in ('delay_events','delay_audit')) + ('delay.keep' = any(pt_rights()))::int + ('dly' = any(pt_screens()))::int + pt_right_default('plan','delay.keep')::int, 20),
('v25', (select count(*) from pg_proc where proname in ('delay_lists_set','pt_dly_list','pt_dly_list_default')) + (select count(*) from delay_lists) + (select count(*) from pg_policies where tablename in ('delay_lists','delay_list_audit')) + (pt_dly_label('owner') = 'Claim owner')::int, 12),
('v26', (select count(*) from pg_proc where proname in ('delay_corr_act','delay_corr_features','pt_dly_corr_link','pt_dly_file_can','pt_dly_corr_guard')) + (select count(*) from storage.buckets where id = 'delay-docs' and not public) + (select count(*) from pg_policies where (tablename = 'delay_corr' and policyname = 'dc_read') or policyname in ('protrack_delay_docs_read','protrack_delay_docs_add')) + (select count(*) from pg_trigger where tgname = 'trg_dly_corr_guard'), 10),
('v27', (select count(*) from pg_tables where tablename in ('co_actuals','co_batches','co_opening','co_po_terms','co_other_lines','co_versions','co_reviews','co_scenarios','co_maps','co_audit')) + (select count(*) from pg_proc where proname in ('cashout_act','cashout_features','pt_co_keeper','pt_co_uploader','pt_co_approver','pt_co_publisher','pt_co_ms')) + ('cashout.keep' = any(pt_rights()))::int + ('cout' = any(pt_screens()))::int + pt_right_default('costing','cashout.keep')::int, 20),
('v28', (select count(*) from pg_tables where tablename in ('co_mat_po','co_heads')) + (select count(*) from pg_proc where proname in ('cashout_act','cashout_act_v27','pt_co_mat_ms')) + (select count(*) from pg_policies where tablename in ('co_mat_po','co_heads')) + ((cashout_features() ->> 'version') = '28')::int, 8),
('v29', (select count(*) from pg_tables where tablename in ('rs_config','rs_exemptions','rs_reminders')) + (select count(*) from pg_proc where proname in ('reporting_act','reporting_features','pt_rs_reminder_ok')) + (select count(*) from rs_config), 7),
('v30', (select count(*) from pg_tables where tablename in ('key_milestones','key_milestone_audit')) + (select count(*) from pg_proc where proname in ('key_milestone_act','pt_key_ms','pt_phase_tbl','release_act_km','pt_km_update')) + array_length(pt_phases(), 1), 15),
('v31', ('boq' = any(pt_screens()))::int, 1),
('v32', (select count(*) from pg_tables where tablename like 'boq\_%') + (select count(*) from pg_proc where proname in ('boq_save','pt_boq','pt_boq_file_can')) + (select count(*) from unnest(pt_rights()) r where r like 'boq.%') + (select count(*) from storage.buckets where id = 'boq-drawings'), 20),
('v33', (select count(*) from pg_proc where proname in ('pt_ep_tbl','ep_features')), 2),
('v34', (select count(*) from pg_proc where proname in ('golive_set','golive_features','doc_text_set','doc_text_info','doc_text_search')) + (select count(*) from pg_tables where tablename in ('golive_cfg','golive_audit','doc_text_meta','doc_text')) + ((select cfg ->> 'current' from golive_cfg) = '4')::int, 10)
) t(v, got, expected) order by length(v), v;
